#include "return_exact_detail.hpp"
#include "hanmo/resident_world_api.hpp"
#include <algorithm>
namespace hanmo::resident {using namespace return_exact_detail;namespace {
void registration(const ActionTimeRegistration& r){if(r.action_kind!="army_return"||r.owner_domain!="military"||r.profile_id!="military_action_time"||r.profile_version!=1||r.source_schema!=2||r.mode!=ActionTimeMode::fixed_duration||r.remaining_meaning!=ActionRemainingMeaning::service_estimate||r.shared_gate_kind||!r.retained_wait_phases.empty())fail("ExactReturnRegistrationMismatch");}
void same_proof(const ActionTimeOwnerProof& a,const ActionTimeOwnerProof& b){if(a.action_ref!=b.action_ref||a.action_kind!=b.action_kind||a.actor_id!=b.actor_id||a.participant_actor_ids!=b.participant_actor_ids||a.phase!=b.phase||a.source_schema!=b.source_schema||!same_source(a.original_execution_source,b.original_execution_source)||a.terminal_result_ref!=b.terminal_result_ref)fail("StaleExactReturnOwnerProof",a.action_ref);}
}
ActionTimeRegistration exact_return_action_registration(){return {"army_return","military","military_action_time",1,2,ActionTimeMode::fixed_duration,ActionRemainingMeaning::service_estimate,{},{}};}
Status NativeReturnActionTimeRead::enumerate_action_time_owners(const ActionTimeRegistration& r,ActionTimeOwnerIdSink& output)const{return status([&]{registration(r);for(const auto& row:state_.dynamic_logistics_facts.rows())if(row.second.command=="army_return"){take(read_action_time_owner(r,row.first));take(output.append(row.first));}});}
Outcome<ActionTimeOwnerProof> NativeReturnActionTimeRead::read_action_time_owner(const ActionTimeRegistration& r,const StableId& id)const{return guard<ActionTimeOwnerProof>([&]{registration(r);bound(common_,military_,state_,context_);const auto& f=fact(state_,id);header(common_,id);take(validate_exact_return_office_authority(common_,military_,state_,context_,f));take(context_.original.validate_return_acceptance(f));
 for(const auto& legacy:military_.logistics_facts)if(legacy.id==id)fail("DuplicateLegacyExactMilitaryAction",id);
 for(const auto& legacy:military_.logistics_actions)if(legacy.action_id==id)fail("DuplicateLegacyExactMilitaryExecution",id);
 if(f.elapsed_source_ref.action_ref!=id||f.rule_version!=2)fail("ExactReturnElapsedBindingMismatch",id);
 const auto original_members=participants(common_,military_,state_,f,context_);CheckpointVector<std::string_view> members,empty;members.reserve(original_members.size());for(const auto* member:original_members)members.push_back(*member);const auto original_source=SourceRefBuildView{"military","military_action",id};
 ActionTimeOwnerProofBuildView proof{id,f.command,f.actor_id,{members},original_source,2,MomentOwnerSourceBuildView{original_source,2},ActionTimeOwnerPhase::working,{},{},{},{empty},{}};
 if(f.phase=="completed"){if(!f.completed_at||!f.result)fail("ExactReturnResultRequired",id);proof.phase=ActionTimeOwnerPhase::terminal;proof.ended_source=MomentOwnerSourceBuildView{{"military","military_logistics_completed",id},2};proof.terminal_result_ref=id;}
 else if(f.phase=="started"){const auto* a=common_.action(id);if(!a||a->kind!=f.command||a->actor_id!=f.actor_id||!std::equal(a->participants.begin(),a->participants.end(),members.begin(),members.end())||a->start_tick!=f.started_at.half_day_tick)fail("ExactReturnActualActionRequired",id);proof.phase=ActionTimeOwnerPhase::working;}
 else fail("InvalidExactReturnPhase",id);return ActionTimeOwnerProof(proof);
});}
Outcome<WorldMoment> NativeReturnActionTimeRead::read_action_time_source(const ElapsedTimeSource& source)const{return guard<WorldMoment>([&]{const auto* original=std::get_if<MomentOwnerSource>(&source);if(!original||original->source_schema!=2||original->source_ref.domain!="military")fail("ExactReturnMomentSourceRequired");const auto& ref=original->source_ref;const auto& f=fact(state_,ref.id);header(common_,f.id);if(ref.kind=="military_action")return f.started_at;if(ref.kind=="military_logistics_completed"&&f.phase=="completed"&&f.completed_at&&f.result)return *f.completed_at;fail("ExactReturnMomentSourceRequired",ref.id);});}
Status NativeReturnActionTimeRead::validate_fixed_action_sources(const ActionTimeRegistration& r,const ActionTimeOwnerProof& supplied,const ActionElapsedState& entry,const std::vector<FixedServiceTransition>& transitions)const{return status([&]{registration(r);same_proof(take(read_action_time_owner(r,entry.action_ref)),supplied);const auto& f=fact(state_,entry.action_ref);take(validate_fact_history(common_,military_,state_,context_,f,entry,true));const bool terminal=f.phase=="completed";if(transitions.size()!=(terminal?2u:1u))fail("ExactReturnFixedHistoryMismatch",f.id);
 for(std::size_t i=0;i<transitions.size();++i){const auto& t=transitions[i];if(t.source_schema!=1||t.action_ref!=f.id||t.transition_ordinal!=Integer(i)||t.execution_source_schema!=2||!same_source(t.execution_source_ref,start_ref(f.id)))fail("ExactReturnFixedSourceMismatch",f.id);
  if(i==0){const auto* cause=std::get_if<FixedOwnerAdopted>(&t.cause);if(t.kind!=FixedTransitionKind::started||t.previous_transition_ref||!cause||cause->owner_source_schema!=2||!same_source(cause->owner_source_ref,start_ref(f.id))||!same_moment(t.occurred_at,f.started_at,context_.budget)||compare(t.credited_at.value,integer(0,context_.budget),context_.budget)||t.input_basis_refs.size()!=1||t.terminal_disposition)fail("ExactReturnStartedHistoryMismatch",f.id);const auto* input=std::get_if<FixedAppliedInput>(&t.input_basis_refs.front());if(!input||input->source_schema!=2||!same_source(input->source_ref,start_ref(f.id)))fail("ExactReturnAdoptedInputRequired",f.id);}
  else{const auto* cause=std::get_if<FixedOwnerTerminated>(&t.cause);if(t.kind!=FixedTransitionKind::terminal||!cause||cause->owner_result_schema!=2||!same_source(cause->owner_result_ref,completed_ref(f.id))||t.previous_transition_ref!=std::optional<StableId>{transitions.front().transition_id}||!same_moment(t.occurred_at,*f.completed_at,context_.budget)||compare(t.credited_at.value,entry.required_units.value,context_.budget)||t.terminal_disposition!=std::optional<FixedTerminalDisposition>{f.success?FixedTerminalDisposition::completed:FixedTerminalDisposition::interrupted})fail("ExactReturnTerminalHistoryMismatch",f.id);}
 }
});}
Status NativeReturnActionTimeRead::validate_shared_action_sources(const ActionTimeRegistration&,const ActionTimeOwnerProof&,const SharedWorkElapsedState&)const{return common_failure("ExactReturnDoesNotOwnSharedWork");}
Outcome<RunStop> NativeReturnActionTimeRead::read_action_continuation_stop(const ActionTimeRegistration& r,const ActionTimeOwnerProof& supplied,const WorldMoment& now)const{return guard<RunStop>([&]{const auto proof=take(read_action_time_owner(r,supplied.action_ref));same_proof(proof,supplied);const auto& f=fact(state_,proof.action_ref);if(f.phase=="completed")return f.success?RunStop::completed:RunStop::blocked;const auto* entry=find_fixed_elapsed(elapsed_,f.id);if(!entry||take(compare_world_moments(entry->last_settled_at,now,context_.budget))>0)fail("ExactReturnElapsedRequired",f.id);return RunStop::budget_exhausted;});}
Outcome<OriginalActionRemaining> NativeReturnActionTimeRead::read_original_action_remaining(const ActionTimeRegistration& r,const ActionTimeOwnerProof& supplied,const WorldMoment&)const{return guard<OriginalActionRemaining>([&]()->OriginalActionRemaining{const auto proof=take(read_action_time_owner(r,supplied.action_ref));same_proof(proof,supplied);const auto* entry=find_fixed_elapsed(elapsed_,proof.action_ref);if(!entry)fail("ExactReturnElapsedRequired",proof.action_ref);return ActualServiceRemaining{ActualServiceRemainingBuildView{proof.phase==ActionTimeOwnerPhase::terminal?HalfDayDuration{}:take(scale_units_to_duration(take(subtract_work_units(entry->required_units,entry->credited_units,context_.budget)),context_.scale.units_per_half_day,context_.budget)),{proof.original_execution_source.domain,proof.original_execution_source.kind,proof.original_execution_source.id},2}};});}
Outcome<StableId> NativeReturnActionTimeRead::read_gate_result_id(const SharedWorkGateResult&)const{return {false,{},common_failure("ExactReturnDoesNotOwnSharedWork").error};}
Outcome<SharedWorkGateResult> NativeReturnActionTimeRead::read_original_gate_result(const StableId&)const{return {false,{},common_failure("ExactReturnDoesNotOwnSharedWork").error};}
Status NativeReturnActionTimeRead::validate_original_gate_result(const SharedWorkGateResult&)const{return common_failure("ExactReturnDoesNotOwnSharedWork");}
}
